import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../core/providers/repository_providers.dart';
import '../../core/session/operator_session.dart';
import '../../data/models/asset.dart';
import '../../core/layout/responsive_layout.dart';

class AssetInventoryScreen extends ConsumerStatefulWidget{const AssetInventoryScreen({super.key});@override ConsumerState<AssetInventoryScreen> createState()=>_AssetInventoryScreenState();}
class _AssetInventoryScreenState extends ConsumerState<AssetInventoryScreen>{int _refresh=0;
  Future<void> _start() async {final repo=ref.read(assetRepositoryProvider);final locs=await repo.locations();if(!mounted)return;final label=TextEditingController(text:'Inventaire ${DateTime.now().year}');String? locationId;final ok=await showDialog<bool>(context:context,builder:(context)=>StatefulBuilder(builder:(context,setLocal)=>AlertDialog(title:const Text('Nouvelle campagne d’inventaire'),content:ResponsiveDialogContent(maxWidth:440,child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:label,decoration:const InputDecoration(labelText:'Libellé')),const SizedBox(height:10),DropdownButtonFormField<String?>(isExpanded:true,initialValue:locationId,decoration:const InputDecoration(labelText:'Limiter à une localisation'),items:[const DropdownMenuItem<String?>(value:null,child:Text('Tout le patrimoine')),...locs.map((l)=>DropdownMenuItem<String?>(value:l.id,child:Text(l.name)))],onChanged:(v)=>setLocal(()=>locationId=v))])),actions:[TextButton(onPressed:()=>Navigator.pop(context,false),child:const Text('Annuler')),FilledButton(onPressed:()=>Navigator.pop(context,true),child:const Text('Démarrer'))])));
    if(ok==true){final id=await repo.startInventory(label:label.text,locationId:locationId);if(mounted){await Navigator.push<void>(context,MaterialPageRoute(builder:(_)=>AssetInventoryDetailScreen(sessionId:id,label:label.text,status:'open')));setState(()=>_refresh++);}}label.dispose();}
  @override Widget build(BuildContext context){final repo=ref.read(assetRepositoryProvider);return Scaffold(appBar:AppBar(title:const Text('Inventaires physiques')),floatingActionButton:OperatorSession.isReadOnly?null:FloatingActionButton.extended(onPressed:_start,icon:const Icon(Icons.add),label:const Text('Nouvel inventaire')),body:FutureBuilder<List<AssetInventorySessionItem>>(key:ValueKey(_refresh),future:repo.inventorySessions(),builder:(context,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());if(s.data!.isEmpty)return const Center(child:Text('Aucune campagne d’inventaire.'));return ListView.separated(padding:const EdgeInsets.fromLTRB(16,16,16,90),itemCount:s.data!.length,separatorBuilder:(_,__)=>const SizedBox(height:6),itemBuilder:(context,i){final x=s.data![i];return Card(child:ListTile(leading:CircleAvatar(child:Icon(x.status=='completed'?Icons.fact_check:Icons.pending_actions)),title:Text(x.label,style:const TextStyle(fontWeight:FontWeight.w800)),subtitle:Text('${x.checked}/${x.total} vérifiés · ${x.missing} manquant(s) · ${x.damaged} endommagé(s)'),trailing:const Icon(Icons.chevron_right),onTap:()async{await Navigator.push<void>(context,MaterialPageRoute(builder:(_)=>AssetInventoryDetailScreen(sessionId:x.id,label:x.label,status:x.status)));if(mounted)setState(()=>_refresh++);}));});}));}
}

class AssetInventoryDetailScreen extends ConsumerStatefulWidget{const AssetInventoryDetailScreen({super.key,required this.sessionId,required this.label,required this.status});final String sessionId,label,status;@override ConsumerState<AssetInventoryDetailScreen> createState()=>_AssetInventoryDetailScreenState();}
class _AssetInventoryDetailScreenState extends ConsumerState<AssetInventoryDetailScreen>{int _refresh=0;
  Future<void> _check(Map<String,Object?> row) async {String result='found';final note=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(context)=>StatefulBuilder(builder:(context,setLocal)=>AlertDialog(title:Text('${row['asset_number']} · ${row['name']}'),content:ResponsiveDialogContent(maxWidth:430,child:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField<String>(initialValue:result,decoration:const InputDecoration(labelText:'Résultat'),items:const[DropdownMenuItem(value:'found',child:Text('Trouvé')),DropdownMenuItem(value:'missing',child:Text('Manquant')),DropdownMenuItem(value:'moved',child:Text('Déplacé')),DropdownMenuItem(value:'damaged',child:Text('Endommagé'))],onChanged:(v)=>setLocal(()=>result=v??'found')),const SizedBox(height:10),TextField(controller:note,decoration:const InputDecoration(labelText:'Observation'))])),actions:[TextButton(onPressed:()=>Navigator.pop(context,false),child:const Text('Annuler')),FilledButton(onPressed:()=>Navigator.pop(context,true),child:const Text('Valider'))])));
    if(ok==true){await ref.read(assetRepositoryProvider).checkInventoryItem(itemId:row['id'] as String,result:result,note:note.text,observedCondition:result=='damaged'?'repair':null);if(mounted)setState(()=>_refresh++);}note.dispose();}
  Future<void> _complete() async{try{await ref.read(assetRepositoryProvider).completeInventory(widget.sessionId);if(mounted)Navigator.pop(context);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}}
  @override Widget build(BuildContext context){final repo=ref.read(assetRepositoryProvider);return Scaffold(appBar:AppBar(title:Text(widget.label),actions:[if(widget.status=='open'&&!OperatorSession.isReadOnly)IconButton(onPressed:_complete,tooltip:'Clôturer',icon:const Icon(Icons.check_circle_outline))]),body:FutureBuilder<List<Map<String,Object?>>>(key:ValueKey(_refresh),future:repo.inventoryItems(widget.sessionId),builder:(context,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView.separated(padding:const EdgeInsets.all(16),itemCount:s.data!.length,separatorBuilder:(_,__)=>const SizedBox(height:5),itemBuilder:(context,i){final r=s.data![i];final result='${r['result']}';return Card(child:ListTile(leading:CircleAvatar(child:Icon(result=='not_checked'?Icons.help_outline:result=='missing'?Icons.search_off:result=='damaged'?Icons.warning_amber:Icons.check)),title:Text('${r['asset_number']} · ${r['name']}'),subtitle:Text('Attendu : ${r['expected_location']??'Non localisé'} · Résultat : $result${r['note']==null?'':'\n${r['note']}'}'),onTap:widget.status=='open'&&!OperatorSession.isReadOnly?()=>_check(r):null));});}));}
}
